DOZING = '1,2,3,10,11,12,23,24,54,56,57,69,70,71,92,93,94,127,147,148,149,152,153,154,194_Paldea,197,198,200,213,214,215,225,228,229,248,252,253,254,288,302,316,317,334,353,354,359,371,372,373,380,381,387,388,425,426,429,430,442,453,454,461,470,491,557,558,590,591,710_Small,710_Medium,710_Large,710_Jumbo,711_Small,711_Medium,711_Large,711_Jumbo,714,715,736,737,738,778,780,849_Amped,849_Low Key,906,907,908,911,980_Paldea'
SLUMBERING = '7,8,9,27,28,37_Alola,38_Alola,55,74,75,76,81,82,83,84,85,95,104,105,134,158,159,160,172,173,174,175,185,194,195,208,245,246,247,256,257,258,259,260,303,304,305,306,328,329,330,333,360,363,363_Holiday,364,365,389,391,392,393,394,395,438,439,440,447,448,459,460,462,471,475,627,628,696,697,701,759,760,777,845,848,912,913,914,974,975'
REGIONAL_SPRITE_IDS = {"37:Alola":10103, "38:Alola":10104, "194:Paldea":10253}

FORM_TOKENS = {"アローラ":"Alola", "パルデア":"Paldea", "ホリデー":"Holiday", "ハロウィン":"Halloween", "キャプテン":"Captain", "こだましゅ":"Small", "ちゅうだましゅ":"Medium", "おおだましゅ":"Large", "ギガだましゅ":"Jumbo", "ハイ":"Amped", "ロー":"Low Key"}


def species_key(num, name):
    form = ''
    if '(' in name or '（' in name:
        form_name = name.split('(')[-1].rstrip(')') if '(' in name else name.split('（')[-1].rstrip('）')
        form = FORM_TOKENS.get(form_name, '')
    if name == 'Pikachu (Low Key)':
        form = 'Low Key'
    if num == 980:
        form = 'Paldea'
    return f'{num}:{form or "default"}', form


def make_seed():
    dozing = set(DOZING.split(',')); slumbering = set(SLUMBERING.split(','))
    species=[]
    for part in NAMES.split('|'):
        num, name = part.split(':',1); num=int(num)
        key, form=species_key(num,name)
        ident = str(num)+ ('_'+form if form else '')
        sleep = 'うとうと' if ident in dozing else ('ぐっすり' if ident in slumbering else 'すやすや')
        item=dict(key=key,id=num,name=name,sleep=sleep,islands=[],form=form)
        if key in REGIONAL_SPRITE_IDS:item['spriteId']=REGIONAL_SPRITE_IDS[key]
        species.append(item)
    assert len(species)==252, len(species)
    assert len({x['key'] for x in species})==len(species)
    return {"schema":1,"updatedAt":"2026-11-01","source":"species-only seed (nitoyon/pokesleep-tool); island availability not yet imported","areasReady":False,"areas":[],"pokemon":species}

if __name__ == '__main__':
    root=Path(__file__).resolve().parents[1]
    (root/'data'/'master.json').write_text(json.dumps(make_seed(),ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf-8')
    print(f'seeded {len(make_seed()["pokemon"])} Pokémon')
